gen=f'''<div class="pane">{ltabs("Media")}<div class="back">{ic("l")}Generate</div>
<div class="sub" style="padding-top:0"><span class="chipbtn on">Video</span><span class="chipbtn">Image</span></div>
<div class="ta">Brass phonograph on a cluttered lab bench, 1900s, warm tungsten light, film grain, slow push-in</div>
<div class="refs"><div class="img"></div><div>{ic("plus")}</div><span style="color:var(--dim);font-size:11.5px;align-self:center">Reference or first frame</span></div>
<div style="padding:0 10px"><div class="fl"><label>Model</label><div class="inp">Kling 2.1 · fal {ic("down")}</div></div>
<div class="fl"><label>Aspect</label><div class="opts"><div class="on">16:9</div><div>9:16</div><div>1:1</div></div></div>
<div class="fl"><label>Duration</label><div class="opts"><div>5s</div><div class="on">6s</div><div>10s</div></div></div>
<div class="fl"><label>Variations</label><div class="opts"><div class="on">1</div><div>2</div><div>4</div></div></div></div>
<div class="foot"><span style="color:var(--muted);font-size:12px">≈ $0.40 · network</span><div class="sp"></div><div class="b acc">{ic("spark")}Generate</div></div></div>'''
page("m6",gen+viewer(),"360px 1fr","<b>Generate sub-view</b> inside Media (and Audio for music, SFX and voice). The back arrow returns to the grid. Results land in the grid with a progress overlay and appear in the jobs indicator. Model-specific options appear only when relevant.")

# m7 export + jobs popovers
exp=f'''<div class="pop" style="right:10px;top:92px;width:330px">
<div class="fl"><label>Name</label><div class="inp">Edison intro</div></div>
<div class="fl"><label>Save to</label><div class="inp" style="color:var(--muted)">~/Movies/Video Creater {ic("folder")}</div></div>
<div class="fl"><label>Format</label><div class="opts"><div class="on">MP4</div><div>ProRes</div><div>WebM</div></div></div>
<div class="fl"><label>Resolution</label><div class="opts"><div>720p</div><div class="on">1080p</div><div>4K</div></div></div>
<div class="fl"><label>Quality</label><div class="opts"><div>Draft</div><div class="on">High</div><div>Master</div></div></div>
<div style="display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin:2px 0 12px">H.264 · 30 fps · ≈ 84 MB<span>Advanced {ic("down")}</span></div>
<div class="b acc" style="width:100%">Export video</div>
<div style="border-top:1px solid var(--line);margin:12px -14px 0;padding:10px 14px 0;color:var(--muted);font-size:12px;display:flex;gap:10px">Also export: <u>Premiere XML</u><u>DaVinci XML</u><u>Project package</u></div></div>'''
jobs=f'''<div class="pop" style="right:350px;top:92px;width:330px;padding:8px 12px">
<div style="font-weight:600;padding:4px 4px 6px">Background tasks</div>
<div class="job"><span class="jic">{ic("cc")}</span><div>Transcribing input.mp4<div class="bar"><i style="width:62%"></i></div></div><div class="ib sm">{ic("x")}</div></div>
<div class="job"><span class="jic">{ic("spark")}</span><div>Generating “lab bench”<small>Queued · fal</small></div><div class="ib sm">{ic("x")}</div></div>
<div class="job"><span class="jic" style="color:#5ee0a8">{ic("check")}</span><div>Exported Edison intro.mp4<small>2 min ago</small></div><span class="b" style="height:26px">Show</span></div>
<div class="job"><span class="jic" style="color:#ff7a7a">!</span><div>Draft render failed<small>Missing font “Canela” · <u>Retry</u> · <u>Log</u></small></div><span></span></div></div>'''
page("m7",agent1+viewer(),"380px 1fr","<b>Export popover</b> (one entry point) and the <b>jobs popover</b> opened from the indicator. The jobs list replaces the Activity rail, the Render status button and the inspector render tab. Failures say what broke and offer Retry and Log.",extra=exp+jobs)
